package net.civeira.phylax.features.access.userpersonalapikey.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userpersonalapikey.domain.UserPersonalApiKey;
import net.civeira.phylax.features.access.userpersonalapikey.domain.valueobject.ScopesVO;

@RequiredArgsConstructor
public class ScopesValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ScopesVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getScopes() {
    return value.map(ScopesVO::getScopes);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ScopesVO> getScopesValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ScopesVO readScopes(final Optional<UserPersonalApiKey> original,
      final ConstraintFailList fails) {
    ScopesVO result = value.orElse(original.map(UserPersonalApiKey::getScopesValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "scopes", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scopes
   * @return
   */
  public T scopes(ScopesVO scopes) {
    this.value = Optional.of(scopes);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scopes
   * @return
   */
  public T scopes(Optional<ScopesVO> scopes) {
    this.value = scopes;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scopes
   * @return
   */
  public T scopes(String scopes) {
    this.value = Optional.of(ScopesVO.from(scopes));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetScopes() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetScopesIfMatches(final String field) {
    if ("scopes".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
